#!/usr/bin/env bash
set -eo pipefail
readonly SEQUENCE=225
readonly OUTPUT_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_slz_survey_development_20260928_v1"
readonly SOURCE_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/workspace"
readonly RUNS_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/runs"
readonly PYTHON_BIN="/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python"
readonly PYTHON_ENV_ROOT="/data1/home/sunyiq/miniconda3/envs/nh_final"
readonly PYTHON_RESOLVED="/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python3.11"
readonly PYTHON_SHA256="45140eba20e770e6f8b46fb1e1295da8a5e494b3686a22ea9beeff050bb5b48e"
readonly JOB_NAME="kdpp_slz_survey"
readonly BUNDLE_SHA="cdd9a58abae5de5211f78c6d4ce543fb57cf9c5a60c7c5022f2e98a5c2591184"
readonly PAYLOAD=''
echo "SLZ_SURVEY_SUBMIT_V1"
echo "sequence=$SEQUENCE"
echo "timestamp_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "host=$(hostname)"
if [[ -e "$OUTPUT_ROOT" ]]; then echo "REFUSING: output root already exists" >&2; exit 20; fi
if [[ ! -d "$SOURCE_ROOT" || -L "$SOURCE_ROOT" || ! -d "$RUNS_ROOT" || -L "$RUNS_ROOT" ]]; then
  echo "REFUSING: a frozen root or Python is absent" >&2; exit 21
fi
if [[ ! -e "$PYTHON_BIN" || ! -x "$PYTHON_BIN" || ! -L "$PYTHON_BIN" ]]; then
  echo "REFUSING: requested Python symbolic link differs" >&2; exit 32
fi
actual_python=$(readlink -f -- "$PYTHON_BIN") || { echo "REFUSING: Python link cannot be resolved" >&2; exit 32; }
case "$actual_python" in
  "$PYTHON_ENV_ROOT"/bin/python*) ;;
  *) echo "REFUSING: resolved Python left the approved environment" >&2; exit 32 ;;
esac
if [[ "$actual_python" != "$PYTHON_RESOLVED" || ! -f "$actual_python" || ! -x "$actual_python" || -L "$actual_python" ]]; then
  echo "REFUSING: resolved Python path changed after admission" >&2; exit 32
fi
actual_python_sha=$(sha256sum -- "$actual_python" | awk '{print $1}')
if [[ "$actual_python_sha" != "$PYTHON_SHA256" ]]; then
  echo "REFUSING: resolved Python bytes changed after admission" >&2; exit 33
fi
own_queue=$(squeue -u "$USER" -h -o '%i|%j|%T|%P|%R' 2>&1)
echo "OWN_QUEUE_BEGIN"
printf '%s\n' "$own_queue"
echo "OWN_QUEUE_END"
if printf '%s\n' "$own_queue" | grep -Fq '|hcpu48|'; then echo "REFUSING: user already has an hcpu48 job" >&2; exit 22; fi
if printf '%s\n' "$own_queue" | grep -Fq "|$JOB_NAME|"; then echo "REFUSING: unique job name already exists" >&2; exit 23; fi
idle_nodes=$(sinfo -h -p hcpu48 -t idle -o '%D' | awk '{sum += $1} END {print sum + 0}')
echo "hcpu48_idle_nodes=$idle_nodes"
if [[ "$idle_nodes" -lt 1 ]]; then echo "REFUSING: no idle hcpu48 node" >&2; exit 24; fi
partition_rules=$(scontrol show partition hcpu48)
if ! printf '%s\n' "$partition_rules" | grep -Fq 'OverSubscribe=EXCLUSIVE'; then echo "REFUSING: allocation rule changed" >&2; exit 25; fi
if ! printf '%s\n' "$partition_rules" | grep -Fq 'State=UP'; then echo "REFUSING: partition is not up" >&2; exit 26; fi
if ! printf '%s\n' "$partition_rules" | grep -Fq 'MaxTime=UNLIMITED'; then echo "REFUSING: partition maximum time requires renewed review" >&2; exit 27; fi
payload_sha=$(printf '%s' "$PAYLOAD" | base64 --decode | sha256sum | awk '{print $1}')
if [[ "$payload_sha" != "$BUNDLE_SHA" ]]; then echo "REFUSING: embedded payload digest differs" >&2; exit 28; fi
mkdir "$OUTPUT_ROOT"
mkdir "$OUTPUT_ROOT/payload" "$OUTPUT_ROOT/logs" "$OUTPUT_ROOT/tmp"
printf '%s' "$PAYLOAD" | base64 --decode | tar -xz -C "$OUTPUT_ROOT/payload"
printf '%s  %s\n' '3fc0a6799cf54e21eeacb45d184f82f17e4ca488c85d9195cbba34bf6a1527b0' "$OUTPUT_ROOT/payload/bundle_manifest.json" | sha256sum --check --strict
printf '%s  %s\n' \
  'b086a2ba813dce2262c7f8816ad42b3959b53cd042e64e9172ac2b289517465e' "$OUTPUT_ROOT/payload/run_slz_survey.py" \
  'd1f8454dc1e105b31dc048299762fc0759d6ffe6e01e2e615807d0448d75c4b3' "$OUTPUT_ROOT/payload/run_training_mode_replay.py" \
  '308c72cff1ee1c269f8b5a641d907128364da9a917de199ed0383fe32a8d7110' "$OUTPUT_ROOT/payload/run_coldstart_intervention.py" \
  '1678c7ceaec04084ff2c6c2ad13f337cb290ed15c55e6588a069dc75fea2f624' "$OUTPUT_ROOT/payload/authorization_survey.json" \
  'a6dbb1244cfd3bb0f4f98b2d236faa906b0c31672085322c00865bf5016d8473' "$OUTPUT_ROOT/payload/registered_inputs.json" \
  'f7ee4b0a8949b0c37d970541ffbce0dcf6b06213572d2ceee812998072f4c2b4' "$OUTPUT_ROOT/payload/submit.slurm" \
  '030e8cce6c4818e35fba9dc22fb39e93fb118996ea1e77706f50c2367cd49ffe' "$OUTPUT_ROOT/payload/source_manifest.json" | sha256sum --check --strict
PYTHONDONTWRITEBYTECODE=1 "$actual_python" -B - "$RUNS_ROOT" "$OUTPUT_ROOT/payload/registered_inputs.json" <<'PY'
from hashlib import sha256
import json
from pathlib import Path
import sys

runs_root = Path(sys.argv[1])
registered = json.loads(Path(sys.argv[2]).read_bytes())
family = "DAILY_CAMELS_KNET_ALIGNED_REMATCH_V3_20260916"

def digest(path):
    value = sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()

if len(registered.get("runs", {})) != 105:
    raise SystemExit("REGISTERED_RUN_COUNT_CHANGED")
for key, wanted in sorted(registered["runs"].items()):
    basin, seed_text = key.split("/")
    seed = int(seed_text)
    run_dir = runs_root / f"{family}_KNET_BASIN_{basin}_SEED_{seed}"
    summary = run_dir / "result_summary.json"
    marker = run_dir / "completion.marker.json"
    history = run_dir / "epoch_history.json"
    epoch = int(wanted["best_epoch"])
    checkpoint = run_dir / f"checkpoints/epoch_{epoch:03d}.pt"
    actual = {
        "summary_sha256": digest(summary),
        "marker_sha256": digest(marker),
        "epoch_history_sha256": digest(history),
        "best_checkpoint_sha256": digest(checkpoint),
    }
    if any(actual[name] != wanted[name] for name in actual):
        raise SystemExit(f"RUN_CHANGED_AFTER_ADMISSION|{key}")
print("REBIND_OK|runs=105")
PY
bash -n "$OUTPUT_ROOT/payload/submit.slurm"
chmod 0555 "$OUTPUT_ROOT/payload/submit.slurm"
echo "STAGED_BUNDLE_SHA=$BUNDLE_SHA"
submit_output=$(sbatch "$OUTPUT_ROOT/payload/submit.slurm" 2>&1) || { printf '%s\n' "$submit_output"; exit 30; }
printf '%s\n' "$submit_output"
receipt_lines=$(printf '%s\n' "$submit_output" | grep -E '^Submitted batch job [0-9]+$' || true)
receipt_count=$(printf '%s' "$receipt_lines" | grep -c . || true)
if [[ "$receipt_count" -ne 1 ]]; then echo "NO_SINGLE_CANONICAL_SCHEDULER_RECEIPT count=$receipt_count" >&2; exit 31; fi
job_id=$(printf '%s\n' "$receipt_lines" | grep -oE '[0-9]+$')
submitted_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
printf '{"schema_version":"daily_camels_slz_survey_submission_receipt_v1","job_id":"%s","job_name":"%s","partition":"hcpu48","submitted_at_utc":"%s","retry_allowed":false,"bundle_sha256":"%s"}\n' "$job_id" "$JOB_NAME" "$submitted_at" "$BUNDLE_SHA" > "$OUTPUT_ROOT/submission_receipt.json"
chmod 0444 "$OUTPUT_ROOT/submission_receipt.json"
echo "job_id=$job_id"
echo "output_root=$OUTPUT_ROOT"
